-- Existing submissions, enrollment status, task timing and assessment data are untouched.
BEGIN;
CREATE TEMP TABLE curriculum_revised (payload jsonb NOT NULL) ON COMMIT DROP;
INSERT INTO curriculum_revised(payload) VALUES ($guide_payload$[{"slug":"talora-graphic-design-2026","task_number":1,"title":"Design Brief","old_instructions":"[[AZ]]\n## Məqsəd\nNümunə brend seç ;  Auditoriya və istifadə kontekstini yaz ;  Beş dizayn meyarı müəyyən et.\n\n## Addım-addım icra\n1. Nümunə brend seç.\n2. Auditoriya və istifadə kontekstini yaz.\n3. Beş dizayn meyarı müəyyən et.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nDesign brief. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nChoose a fictional brand ;  Define audience and usage ;  Set five measurable design criteria.\n\n## Step-by-step\n1. Choose a fictional brand.\n2. Define audience and usage.\n3. Set five measurable design criteria.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nDesign brief. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nNümunə brend seç ;  Auditoriya və istifadə kontekstini yaz ;  Beş dizayn meyarı müəyyən et.\n\n[[EN]]\nChoose a fictional brand ;  Define audience and usage ;  Set five measurable design criteria.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Design Brief\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Dizayn həm gözəl, həm oxunaqlı, həm də başqasına təhvil verilə bilən olmalıdır.\n**Nümunə situasiya:** Uydurma tələbə tədbirləri brendi üçün auditoriya və 5 dizayn meyarını yaz.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Figma Starter** — https://www.figma.com. Pulsuz Starter Draft faylı aç, Frame/Text alətlərini istifadə et; plan limitini nəzərə al.\n- **Google Docs** — https://docs.google.com/document/. Boş sənəd aç, başlıqları və cədvəlləri doldur, PDF kimi yüklə.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Graphic Design / Task-1. Pulsuz dizayn alətində yeni fayl aç; uydurma brend üçün 3 ilkin eskiz, ölçü və vizual istinad hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Nümunə brend seç. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Auditoriya və istifadə kontekstini yaz. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Beş dizayn meyarı müəyyən et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: Uydurma tələbə tədbirləri brendi üçün auditoriya və 5 dizayn meyarını yaz. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Design brief. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nUydurma tələbə tədbirləri brendi üçün auditoriya və 5 dizayn meyarını yaz.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Design brief.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Kontrastı, ölçüləri, mənbə hüququnu və eksportu yoxla.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Design Brief\nThis practical assignment is designed for beginners. Designs should be legible, original and easy to hand off.\n**Example scenario:** Define audience needs and five design criteria for a fictional student-events brand.\n\n## Free tools and platforms\n- **Figma Starter** — https://www.figma.com. Use free Starter drafts, frames and text; respect free-plan limits.\n- **Google Docs** — https://docs.google.com/document/. Create a blank document, organize headings/tables and export PDF.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Graphic Design / Task-1. Start a new design file and prepare three rough sketches, canvas sizes and licensed references.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Choose a fictional brand. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Define audience and usage. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Set five measurable design criteria. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Define audience needs and five design criteria for a fictional student-events brand. Document what worked and any limitations.\n7. Complete the main artifact: Design brief. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nDefine audience needs and five design criteria for a fictional student-events brand.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Design brief.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Check contrast, dimensions, asset rights and exports.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nDesign Brief: Nümunə brend seç. Auditoriya və istifadə kontekstini yaz. Beş dizayn meyarı müəyyən et. Pulsuz alətlər: Figma Starter, Google Docs. Nəticə: Design brief.\n\n[[EN]]\nDesign Brief: Choose a fictional brand. Define audience and usage. Set five measurable design criteria. Free tools: Figma Starter, Google Docs. Output: Design brief."},{"slug":"talora-graphic-design-2026","task_number":2,"title":"Moodboard and Reference Audit","old_instructions":"[[AZ]]\n## Məqsəd\nÜç vizual istiqamət topla ;  Lisenziyaları yoxla ;  İlham və kopyanı ayır.\n\n## Addım-addım icra\n1. Üç vizual istiqamət topla.\n2. Lisenziyaları yoxla.\n3. İlham və kopyanı ayır.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nMoodboard with source credits. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nCollect three visual directions ;  Verify asset licenses ;  Distinguish inspiration from imitation.\n\n## Step-by-step\n1. Collect three visual directions.\n2. Verify asset licenses.\n3. Distinguish inspiration from imitation.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nMoodboard and source credits. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nÜç vizual istiqamət topla ;  Lisenziyaları yoxla ;  İlham və kopyanı ayır.\n\n[[EN]]\nCollect three visual directions ;  Verify asset licenses ;  Distinguish inspiration from imitation.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Moodboard and Reference Audit\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Dizayn həm gözəl, həm oxunaqlı, həm də başqasına təhvil verilə bilən olmalıdır.\n**Nümunə situasiya:** Minimalist, enerjili və akademik istiqamətlərdə moodboard düzəlt; qaynaqları yaz.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Canva Free** — https://www.canva.com. Yalnız Free elementlərdən istifadə et, nəticəni PNG/PDF ixrac et; Pro elementə pul vermə.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Graphic Design / Task-2. Pulsuz dizayn alətində yeni fayl aç; uydurma brend üçün 3 ilkin eskiz, ölçü və vizual istinad hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Üç vizual istiqamət topla. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Lisenziyaları yoxla. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. İlham və kopyanı ayır. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: Minimalist, enerjili və akademik istiqamətlərdə moodboard düzəlt; qaynaqları yaz. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Moodboard with source credits. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nMinimalist, enerjili və akademik istiqamətlərdə moodboard düzəlt; qaynaqları yaz.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Moodboard with source credits.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Kontrastı, ölçüləri, mənbə hüququnu və eksportu yoxla.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Moodboard and Reference Audit\nThis practical assignment is designed for beginners. Designs should be legible, original and easy to hand off.\n**Example scenario:** Create minimalist, energetic and academic moodboards with source credits.\n\n## Free tools and platforms\n- **Canva Free** — https://www.canva.com. Use only Free elements, export PNG/PDF and avoid Pro assets.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Graphic Design / Task-2. Start a new design file and prepare three rough sketches, canvas sizes and licensed references.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Collect three visual directions. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Verify asset licenses. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Distinguish inspiration from imitation. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Create minimalist, energetic and academic moodboards with source credits. Document what worked and any limitations.\n7. Complete the main artifact: Moodboard and source credits. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nCreate minimalist, energetic and academic moodboards with source credits.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Moodboard and source credits.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Check contrast, dimensions, asset rights and exports.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nMoodboard and Reference Audit: Üç vizual istiqamət topla. Lisenziyaları yoxla. İlham və kopyanı ayır. Pulsuz alətlər: Canva Free. Nəticə: Moodboard with source credits.\n\n[[EN]]\nMoodboard and Reference Audit: Collect three visual directions. Verify asset licenses. Distinguish inspiration from imitation. Free tools: Canva Free. Output: Moodboard and source credits."},{"slug":"talora-graphic-design-2026","task_number":3,"title":"Typography and Grid","old_instructions":"[[AZ]]\n## Məqsəd\nİki şrift cütü sına ;  Şkala və spacing sistemi qur ;  Mobil və desktop oxunaqlığı müqayisə et.\n\n## Addım-addım icra\n1. İki şrift cütü sına.\n2. Şkala və spacing sistemi qur.\n3. Mobil və desktop oxunaqlığı müqayisə et.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nType and grid spec. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nTest two font pairings ;  Create a type/spacing system ;  Compare mobile and desktop readability.\n\n## Step-by-step\n1. Test two font pairings.\n2. Create a type/spacing system.\n3. Compare mobile and desktop readability.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nTypography specification. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nİki şrift cütü sına ;  Şkala və spacing sistemi qur ;  Mobil və desktop oxunaqlığı müqayisə et.\n\n[[EN]]\nTest two font pairings ;  Create a type/spacing system ;  Compare mobile and desktop readability.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Typography and Grid\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Dizayn həm gözəl, həm oxunaqlı, həm də başqasına təhvil verilə bilən olmalıdır.\n**Nümunə situasiya:** 28px başlıq, 18px altbaşlıq, 14px mətn və 8px grid qaydasını sına.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Figma Starter** — https://www.figma.com. Pulsuz Starter Draft faylı aç, Frame/Text alətlərini istifadə et; plan limitini nəzərə al.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Graphic Design / Task-3. Pulsuz dizayn alətində yeni fayl aç; uydurma brend üçün 3 ilkin eskiz, ölçü və vizual istinad hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. İki şrift cütü sına. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Şkala və spacing sistemi qur. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Mobil və desktop oxunaqlığı müqayisə et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: 28px başlıq, 18px altbaşlıq, 14px mətn və 8px grid qaydasını sına. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Type and grid spec. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\n28px başlıq, 18px altbaşlıq, 14px mətn və 8px grid qaydasını sına.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Type and grid spec.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Kontrastı, ölçüləri, mənbə hüququnu və eksportu yoxla.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Typography and Grid\nThis practical assignment is designed for beginners. Designs should be legible, original and easy to hand off.\n**Example scenario:** Test a 28/18/14px type scale and an 8px layout grid.\n\n## Free tools and platforms\n- **Figma Starter** — https://www.figma.com. Use free Starter drafts, frames and text; respect free-plan limits.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Graphic Design / Task-3. Start a new design file and prepare three rough sketches, canvas sizes and licensed references.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Test two font pairings. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Create a type/spacing system. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Compare mobile and desktop readability. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Test a 28/18/14px type scale and an 8px layout grid. Document what worked and any limitations.\n7. Complete the main artifact: Typography specification. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nTest a 28/18/14px type scale and an 8px layout grid.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Typography specification.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Check contrast, dimensions, asset rights and exports.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nTypography and Grid: İki şrift cütü sına. Şkala və spacing sistemi qur. Mobil və desktop oxunaqlığı müqayisə et. Pulsuz alətlər: Figma Starter. Nəticə: Type and grid spec.\n\n[[EN]]\nTypography and Grid: Test two font pairings. Create a type/spacing system. Compare mobile and desktop readability. Free tools: Figma Starter. Output: Typography specification."},{"slug":"talora-graphic-design-2026","task_number":4,"title":"Logo Explorations","old_instructions":"[[AZ]]\n## Məqsəd\nÜç orijinal konsept sketç et ;  Kiçik ölçüdə yoxla ;  Seçilən variantı əsaslandır.\n\n## Addım-addım icra\n1. Üç orijinal konsept sketç et.\n2. Kiçik ölçüdə yoxla.\n3. Seçilən variantı əsaslandır.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nLogo exploration board. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nSketch three original marks ;  Test at small sizes ;  Explain final selection.\n\n## Step-by-step\n1. Sketch three original marks.\n2. Test at small sizes.\n3. Explain final selection.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nLogo exploration board. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nÜç orijinal konsept sketç et ;  Kiçik ölçüdə yoxla ;  Seçilən variantı əsaslandır.\n\n[[EN]]\nSketch three original marks ;  Test at small sizes ;  Explain final selection.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Logo Explorations\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Dizayn həm gözəl, həm oxunaqlı, həm də başqasına təhvil verilə bilən olmalıdır.\n**Nümunə situasiya:** 3 orijinal logomark sketçi yarat, 24px və 64px görünüşünü yoxla.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Inkscape** — https://inkscape.org. Pulsuz vektor redaktorunda SVG yarat və SVG/PNG ixrac et.\n- **Figma Starter** — https://www.figma.com. Pulsuz Starter Draft faylı aç, Frame/Text alətlərini istifadə et; plan limitini nəzərə al.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Graphic Design / Task-4. Pulsuz dizayn alətində yeni fayl aç; uydurma brend üçün 3 ilkin eskiz, ölçü və vizual istinad hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Üç orijinal konsept sketç et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Kiçik ölçüdə yoxla. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Seçilən variantı əsaslandır. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: 3 orijinal logomark sketçi yarat, 24px və 64px görünüşünü yoxla. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Logo exploration board. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\n3 orijinal logomark sketçi yarat, 24px və 64px görünüşünü yoxla.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Logo exploration board.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Kontrastı, ölçüləri, mənbə hüququnu və eksportu yoxla.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Logo Explorations\nThis practical assignment is designed for beginners. Designs should be legible, original and easy to hand off.\n**Example scenario:** Sketch three original logos and test them at 24px and 64px.\n\n## Free tools and platforms\n- **Inkscape** — https://inkscape.org. Create/edit an SVG in the free vector editor, then export SVG/PNG.\n- **Figma Starter** — https://www.figma.com. Use free Starter drafts, frames and text; respect free-plan limits.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Graphic Design / Task-4. Start a new design file and prepare three rough sketches, canvas sizes and licensed references.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Sketch three original marks. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Test at small sizes. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Explain final selection. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Sketch three original logos and test them at 24px and 64px. Document what worked and any limitations.\n7. Complete the main artifact: Logo exploration board. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nSketch three original logos and test them at 24px and 64px.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Logo exploration board.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Check contrast, dimensions, asset rights and exports.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nLogo Explorations: Üç orijinal konsept sketç et. Kiçik ölçüdə yoxla. Seçilən variantı əsaslandır. Pulsuz alətlər: Inkscape, Figma Starter. Nəticə: Logo exploration board.\n\n[[EN]]\nLogo Explorations: Sketch three original marks. Test at small sizes. Explain final selection. Free tools: Inkscape, Figma Starter. Output: Logo exploration board."},{"slug":"talora-graphic-design-2026","task_number":5,"title":"Color and Accessibility","old_instructions":"[[AZ]]\n## Məqsəd\nRəng palitrası hazırla ;  Text contrast ölç ;  Qara-ağ istifadəni sına.\n\n## Addım-addım icra\n1. Rəng palitrası hazırla.\n2. Text contrast ölç.\n3. Qara-ağ istifadəni sına.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nColor tokens and contrast report. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nBuild a palette ;  Check text contrast ;  Test grayscale use.\n\n## Step-by-step\n1. Build a palette.\n2. Check text contrast.\n3. Test grayscale use.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nColor system and contrast report. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nRəng palitrası hazırla ;  Text contrast ölç ;  Qara-ağ istifadəni sına.\n\n[[EN]]\nBuild a palette ;  Check text contrast ;  Test grayscale use.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Color and Accessibility\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Dizayn həm gözəl, həm oxunaqlı, həm də başqasına təhvil verilə bilən olmalıdır.\n**Nümunə situasiya:** Ağ yazı və tünd göy fon üçün kontrastı ölç, 4.5:1 hədəfinə bax.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Figma Starter** — https://www.figma.com. Pulsuz Starter Draft faylı aç, Frame/Text alətlərini istifadə et; plan limitini nəzərə al.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Graphic Design / Task-5. Pulsuz dizayn alətində yeni fayl aç; uydurma brend üçün 3 ilkin eskiz, ölçü və vizual istinad hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Rəng palitrası hazırla. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Text contrast ölç. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Qara-ağ istifadəni sına. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: Ağ yazı və tünd göy fon üçün kontrastı ölç, 4.5:1 hədəfinə bax. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Color tokens and contrast report. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nAğ yazı və tünd göy fon üçün kontrastı ölç, 4.5:1 hədəfinə bax.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Color tokens and contrast report.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Kontrastı, ölçüləri, mənbə hüququnu və eksportu yoxla.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Color and Accessibility\nThis practical assignment is designed for beginners. Designs should be legible, original and easy to hand off.\n**Example scenario:** Measure white-on-navy text contrast against a 4.5:1 normal-text target.\n\n## Free tools and platforms\n- **Figma Starter** — https://www.figma.com. Use free Starter drafts, frames and text; respect free-plan limits.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Graphic Design / Task-5. Start a new design file and prepare three rough sketches, canvas sizes and licensed references.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Build a palette. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Check text contrast. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Test grayscale use. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Measure white-on-navy text contrast against a 4.5:1 normal-text target. Document what worked and any limitations.\n7. Complete the main artifact: Color system and contrast report. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nMeasure white-on-navy text contrast against a 4.5:1 normal-text target.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Color system and contrast report.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Check contrast, dimensions, asset rights and exports.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nColor and Accessibility: Rəng palitrası hazırla. Text contrast ölç. Qara-ağ istifadəni sına. Pulsuz alətlər: Figma Starter. Nəticə: Color tokens and contrast report.\n\n[[EN]]\nColor and Accessibility: Build a palette. Check text contrast. Test grayscale use. Free tools: Figma Starter. Output: Color system and contrast report."},{"slug":"talora-graphic-design-2026","task_number":6,"title":"Social Media Templates","old_instructions":"[[AZ]]\n## Məqsəd\nÜç post şablonu yarat ;  Eyni komponent qaydasını saxla ;  Mətn uzunluğuna uyğunluğu sına.\n\n## Addım-addım icra\n1. Üç post şablonu yarat.\n2. Eyni komponent qaydasını saxla.\n3. Mətn uzunluğuna uyğunluğu sına.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nFigma social template set. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nCreate three post templates ;  Use consistent components ;  Test variable copy lengths.\n\n## Step-by-step\n1. Create three post templates.\n2. Use consistent components.\n3. Test variable copy lengths.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nSocial templates. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nÜç post şablonu yarat ;  Eyni komponent qaydasını saxla ;  Mətn uzunluğuna uyğunluğu sına.\n\n[[EN]]\nCreate three post templates ;  Use consistent components ;  Test variable copy lengths.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Social Media Templates\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Dizayn həm gözəl, həm oxunaqlı, həm də başqasına təhvil verilə bilən olmalıdır.\n**Nümunə situasiya:** Kvadrat post, 1080×1350 feed və 1080×1920 story şablonu düzəlt.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Figma Starter** — https://www.figma.com. Pulsuz Starter Draft faylı aç, Frame/Text alətlərini istifadə et; plan limitini nəzərə al.\n- **Canva Free** — https://www.canva.com. Yalnız Free elementlərdən istifadə et, nəticəni PNG/PDF ixrac et; Pro elementə pul vermə.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Graphic Design / Task-6. Pulsuz dizayn alətində yeni fayl aç; uydurma brend üçün 3 ilkin eskiz, ölçü və vizual istinad hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Üç post şablonu yarat. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Eyni komponent qaydasını saxla. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Mətn uzunluğuna uyğunluğu sına. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: Kvadrat post, 1080×1350 feed və 1080×1920 story şablonu düzəlt. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Figma social template set. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nKvadrat post, 1080×1350 feed və 1080×1920 story şablonu düzəlt.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Figma social template set.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Kontrastı, ölçüləri, mənbə hüququnu və eksportu yoxla.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Social Media Templates\nThis practical assignment is designed for beginners. Designs should be legible, original and easy to hand off.\n**Example scenario:** Build square, feed and story post templates in three sizes.\n\n## Free tools and platforms\n- **Figma Starter** — https://www.figma.com. Use free Starter drafts, frames and text; respect free-plan limits.\n- **Canva Free** — https://www.canva.com. Use only Free elements, export PNG/PDF and avoid Pro assets.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Graphic Design / Task-6. Start a new design file and prepare three rough sketches, canvas sizes and licensed references.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Create three post templates. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Use consistent components. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Test variable copy lengths. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Build square, feed and story post templates in three sizes. Document what worked and any limitations.\n7. Complete the main artifact: Social templates. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nBuild square, feed and story post templates in three sizes.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Social templates.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Check contrast, dimensions, asset rights and exports.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nSocial Media Templates: Üç post şablonu yarat. Eyni komponent qaydasını saxla. Mətn uzunluğuna uyğunluğu sına. Pulsuz alətlər: Figma Starter, Canva Free. Nəticə: Figma social template set.\n\n[[EN]]\nSocial Media Templates: Create three post templates. Use consistent components. Test variable copy lengths. Free tools: Figma Starter, Canva Free. Output: Social templates."},{"slug":"talora-graphic-design-2026","task_number":7,"title":"Infographic Design","old_instructions":"[[AZ]]\n## Məqsəd\nKiçik sintetik dataset seç ;  Məlumatı düzgün qrafiklə göstər ;  Manipulyativ ölçüləri çıxar.\n\n## Addım-addım icra\n1. Kiçik sintetik dataset seç.\n2. Məlumatı düzgün qrafiklə göstər.\n3. Manipulyativ ölçüləri çıxar.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nInfographic and data source note. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nUse a small synthetic dataset ;  Choose faithful chart forms ;  Avoid misleading scales.\n\n## Step-by-step\n1. Use a small synthetic dataset.\n2. Choose faithful chart forms.\n3. Avoid misleading scales.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nInfographic with source note. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nKiçik sintetik dataset seç ;  Məlumatı düzgün qrafiklə göstər ;  Manipulyativ ölçüləri çıxar.\n\n[[EN]]\nUse a small synthetic dataset ;  Choose faithful chart forms ;  Avoid misleading scales.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Infographic Design\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Dizayn həm gözəl, həm oxunaqlı, həm də başqasına təhvil verilə bilən olmalıdır.\n**Nümunə situasiya:** 5 sətir uydurma rəqəmlə dürüst bar chart infoqrafikası yarat.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Google Sheets** — https://sheets.google.com. Yeni cədvəl yarat, sütun adlarını və ən azı 5 sətirlik nümunəni daxil et.\n- **Figma Starter** — https://www.figma.com. Pulsuz Starter Draft faylı aç, Frame/Text alətlərini istifadə et; plan limitini nəzərə al.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Graphic Design / Task-7. Pulsuz dizayn alətində yeni fayl aç; uydurma brend üçün 3 ilkin eskiz, ölçü və vizual istinad hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Kiçik sintetik dataset seç. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Məlumatı düzgün qrafiklə göstər. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Manipulyativ ölçüləri çıxar. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: 5 sətir uydurma rəqəmlə dürüst bar chart infoqrafikası yarat. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Infographic and data source note. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\n5 sətir uydurma rəqəmlə dürüst bar chart infoqrafikası yarat.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Infographic and data source note.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Kontrastı, ölçüləri, mənbə hüququnu və eksportu yoxla.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Infographic Design\nThis practical assignment is designed for beginners. Designs should be legible, original and easy to hand off.\n**Example scenario:** Build an honest bar-chart infographic from five synthetic data points.\n\n## Free tools and platforms\n- **Google Sheets** — https://sheets.google.com. Create a sheet, name the columns and add at least five fictional rows.\n- **Figma Starter** — https://www.figma.com. Use free Starter drafts, frames and text; respect free-plan limits.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Graphic Design / Task-7. Start a new design file and prepare three rough sketches, canvas sizes and licensed references.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Use a small synthetic dataset. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Choose faithful chart forms. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Avoid misleading scales. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Build an honest bar-chart infographic from five synthetic data points. Document what worked and any limitations.\n7. Complete the main artifact: Infographic with source note. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nBuild an honest bar-chart infographic from five synthetic data points.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Infographic with source note.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Check contrast, dimensions, asset rights and exports.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nInfographic Design: Kiçik sintetik dataset seç. Məlumatı düzgün qrafiklə göstər. Manipulyativ ölçüləri çıxar. Pulsuz alətlər: Google Sheets, Figma Starter. Nəticə: Infographic and data source note.\n\n[[EN]]\nInfographic Design: Use a small synthetic dataset. Choose faithful chart forms. Avoid misleading scales. Free tools: Google Sheets, Figma Starter. Output: Infographic with source note."},{"slug":"talora-graphic-design-2026","task_number":8,"title":"Export Standards","old_instructions":"[[AZ]]\n## Məqsəd\nSVG/PNG/PDF variantlarını hazırla ;  Fayl ölçü və keyfiyyətini yoxla ;  Fayl adlandırma qaydası yaz.\n\n## Addım-addım icra\n1. SVG/PNG/PDF variantlarını hazırla.\n2. Fayl ölçü və keyfiyyətini yoxla.\n3. Fayl adlandırma qaydası yaz.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nExport pack. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nExport SVG, PNG and PDF versions ;  Check file quality and size ;  Define naming rules.\n\n## Step-by-step\n1. Export SVG, PNG and PDF versions.\n2. Check file quality and size.\n3. Define naming rules.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nExport package. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nSVG/PNG/PDF variantlarını hazırla ;  Fayl ölçü və keyfiyyətini yoxla ;  Fayl adlandırma qaydası yaz.\n\n[[EN]]\nExport SVG, PNG and PDF versions ;  Check file quality and size ;  Define naming rules.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Export Standards\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Dizayn həm gözəl, həm oxunaqlı, həm də başqasına təhvil verilə bilən olmalıdır.\n**Nümunə situasiya:** SVG loqo, PNG post və PDF guide eksport et, fayl adlarını yoxla.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Inkscape** — https://inkscape.org. Pulsuz vektor redaktorunda SVG yarat və SVG/PNG ixrac et.\n- **Figma Starter** — https://www.figma.com. Pulsuz Starter Draft faylı aç, Frame/Text alətlərini istifadə et; plan limitini nəzərə al.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Graphic Design / Task-8. Pulsuz dizayn alətində yeni fayl aç; uydurma brend üçün 3 ilkin eskiz, ölçü və vizual istinad hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. SVG/PNG/PDF variantlarını hazırla. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Fayl ölçü və keyfiyyətini yoxla. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Fayl adlandırma qaydası yaz. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: SVG loqo, PNG post və PDF guide eksport et, fayl adlarını yoxla. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Export pack. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nSVG loqo, PNG post və PDF guide eksport et, fayl adlarını yoxla.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Export pack.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Kontrastı, ölçüləri, mənbə hüququnu və eksportu yoxla.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Export Standards\nThis practical assignment is designed for beginners. Designs should be legible, original and easy to hand off.\n**Example scenario:** Export SVG, PNG and PDF assets and validate file naming.\n\n## Free tools and platforms\n- **Inkscape** — https://inkscape.org. Create/edit an SVG in the free vector editor, then export SVG/PNG.\n- **Figma Starter** — https://www.figma.com. Use free Starter drafts, frames and text; respect free-plan limits.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Graphic Design / Task-8. Start a new design file and prepare three rough sketches, canvas sizes and licensed references.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Export SVG, PNG and PDF versions. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Check file quality and size. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Define naming rules. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Export SVG, PNG and PDF assets and validate file naming. Document what worked and any limitations.\n7. Complete the main artifact: Export package. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nExport SVG, PNG and PDF assets and validate file naming.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Export package.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Check contrast, dimensions, asset rights and exports.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nExport Standards: SVG/PNG/PDF variantlarını hazırla. Fayl ölçü və keyfiyyətini yoxla. Fayl adlandırma qaydası yaz. Pulsuz alətlər: Inkscape, Figma Starter. Nəticə: Export pack.\n\n[[EN]]\nExport Standards: Export SVG, PNG and PDF versions. Check file quality and size. Define naming rules. Free tools: Inkscape, Figma Starter. Output: Export package."},{"slug":"talora-graphic-design-2026","task_number":9,"title":"Design Review and Iteration","old_instructions":"[[AZ]]\n## Məqsəd\nİki dizayn üçün checklist hazırla ;  Üç test istifadəçisi simulyasiyası qur ;  Geribildirimə görə dəyişiklik et.\n\n## Addım-addım icra\n1. İki dizayn üçün checklist hazırla.\n2. Üç test istifadəçisi simulyasiyası qur.\n3. Geribildirimə görə dəyişiklik et.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nBefore/after design review. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nCreate a review checklist ;  Run three simulated usability reviews ;  Iterate on findings.\n\n## Step-by-step\n1. Create a review checklist.\n2. Run three simulated usability reviews.\n3. Iterate on findings.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nDesign review before/after. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nİki dizayn üçün checklist hazırla ;  Üç test istifadəçisi simulyasiyası qur ;  Geribildirimə görə dəyişiklik et.\n\n[[EN]]\nCreate a review checklist ;  Run three simulated usability reviews ;  Iterate on findings.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Design Review and Iteration\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Dizayn həm gözəl, həm oxunaqlı, həm də başqasına təhvil verilə bilən olmalıdır.\n**Nümunə situasiya:** 2 versiyanın spacing, rəng və oxunaqlığını before/after müqayisə et.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Figma Starter** — https://www.figma.com. Pulsuz Starter Draft faylı aç, Frame/Text alətlərini istifadə et; plan limitini nəzərə al.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Graphic Design / Task-9. Pulsuz dizayn alətində yeni fayl aç; uydurma brend üçün 3 ilkin eskiz, ölçü və vizual istinad hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. İki dizayn üçün checklist hazırla. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. Üç test istifadəçisi simulyasiyası qur. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Geribildirimə görə dəyişiklik et. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: 2 versiyanın spacing, rəng və oxunaqlığını before/after müqayisə et. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Before/after design review. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\n2 versiyanın spacing, rəng və oxunaqlığını before/after müqayisə et.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Before/after design review.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Kontrastı, ölçüləri, mənbə hüququnu və eksportu yoxla.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Design Review and Iteration\nThis practical assignment is designed for beginners. Designs should be legible, original and easy to hand off.\n**Example scenario:** Compare two iterations for spacing, color and readability.\n\n## Free tools and platforms\n- **Figma Starter** — https://www.figma.com. Use free Starter drafts, frames and text; respect free-plan limits.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Graphic Design / Task-9. Start a new design file and prepare three rough sketches, canvas sizes and licensed references.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Create a review checklist. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Run three simulated usability reviews. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Iterate on findings. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Compare two iterations for spacing, color and readability. Document what worked and any limitations.\n7. Complete the main artifact: Design review before/after. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nCompare two iterations for spacing, color and readability.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Design review before/after.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Check contrast, dimensions, asset rights and exports.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nDesign Review and Iteration: İki dizayn üçün checklist hazırla. Üç test istifadəçisi simulyasiyası qur. Geribildirimə görə dəyişiklik et. Pulsuz alətlər: Figma Starter. Nəticə: Before/after design review.\n\n[[EN]]\nDesign Review and Iteration: Create a review checklist. Run three simulated usability reviews. Iterate on findings. Free tools: Figma Starter. Output: Design review before/after."},{"slug":"talora-graphic-design-2026","task_number":10,"title":"Brand Kit Handoff","old_instructions":"[[AZ]]\n## Məqsəd\nLoqo və şablonları birləşdir ;  İstifadə qaydası yaz ;  Edit edilən və eksport faylları paylaş.\n\n## Addım-addım icra\n1. Loqo və şablonları birləşdir.\n2. İstifadə qaydası yaz.\n3. Edit edilən və eksport faylları paylaş.\n4. Nəticəni yoxla, fərziyyələri və məlumat mənbələrini qeyd et.\n\n## Nə təhvil verilməlidir?\nBrand kit və istifadə bələdçisi. Fayl və ya oxuna bilən link, 3–5 cümləlik izah və istifadə edilən mənbələr.\n\n## Qəbul meyarları\nBütün üç addımın nəticəsi artefaktda görünür, verilən nümunələr təkrar yoxlana bilir, uydurma fakt və icazəsiz şəxsi məlumat yoxdur.\n\n[[EN]]\n## Goal\nCombine logo and templates ;  Write usage rules ;  Share editable and exported assets.\n\n## Step-by-step\n1. Combine logo and templates.\n2. Write usage rules.\n3. Share editable and exported assets.\n4. Verify the result; document assumptions and sources.\n\n## Deliverables\nBrand kit and usage guide. Submit a readable file/link, a short explanation and credited sources.\n\n## Acceptance criteria\nEvidence supports all three steps, examples can be reviewed, and no fabricated facts or unauthorized personal data are included.","old_description":"[[AZ]]\nLoqo və şablonları birləşdir ;  İstifadə qaydası yaz ;  Edit edilən və eksport faylları paylaş.\n\n[[EN]]\nCombine logo and templates ;  Write usage rules ;  Share editable and exported assets.","new_instructions":"[[AZ]]\n## Tapşırığın məqsədi: Brand Kit Handoff\nBu tapşırıq birinci dəfə bu sahəni öyrənən tələbə üçün praktik işdir. Dizayn həm gözəl, həm oxunaqlı, həm də başqasına təhvil verilə bilən olmalıdır.\n**Nümunə situasiya:** Loqo, palitra, şrift, şablon və istifadəyə dair qaydaları bir brand kit-də birləşdir.\n\n## Hansı pulsuz alətlər lazımdır?\n- **Figma Starter** — https://www.figma.com. Pulsuz Starter Draft faylı aç, Frame/Text alətlərini istifadə et; plan limitini nəzərə al.\n- **Google Docs** — https://docs.google.com/document/. Boş sənəd aç, başlıqları və cədvəlləri doldur, PDF kimi yüklə.\n> Heç bir pullu abunə, reklam büdcəsi və ya API açarı tələb olunmur. Free plan limiti bitdikdə lokal alternativdən istifadə et. Başqa şəxslərin şifrəsini, şəxsi məlumatını və icazəsiz fayllarını paylaşma.\n\n## Addım-addım icra təlimatı\n1. Öz iş qovluğunu yarat: Talora / Graphic Design / Task-10. Pulsuz dizayn alətində yeni fayl aç; uydurma brend üçün 3 ilkin eskiz, ölçü və vizual istinad hazırla.\n2. Bu tapşırığın məqsədini və istifadəçisini bir cümlədə yaz; nümunədə hansı nəticənin uğur sayılacağını müəyyən et.\n3. Loqo və şablonları birləşdir. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n4. İstifadə qaydası yaz. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n5. Edit edilən və eksport faylları paylaş. Nəticəni təkcə danışma, uyğun sənəd, cədvəl, sxem, dizayn və ya sınaqda nümayiş etdir.\n6. Nümunəni işlə: Loqo, palitra, şrift, şablon və istifadəyə dair qaydaları bir brand kit-də birləşdir. Hansı məqamın düzgün işlədiyini və hansı məhdudiyyətin qaldığını ayrıca izah et.\n7. Əsas artefaktı hazırla: Brand kit və istifadə bələdçisi. Oxuna bilən PDF/fayl və ya paylaşılabilən linki yoxla; redaktə edilən orijinalı da saxla.\n8. Öz işini təkrar yoxla. Üç əsas addımı bitirdiyini göstər; 3–5 cümləlik nəticə, istifadə olunan alətlər və mənbələri qeyd et.\n\n## İşlənmiş nümunə necə görünməlidir?\nLoqo, palitra, şrift, şablon və istifadəyə dair qaydaları bir brand kit-də birləşdir.\nBu nümunəni olduğu kimi kopyalama: öz sintetik ssenarinə uyğun doldur, araşdırdığın faktları və fərziyyələri ayır.\n\n## Nə təhvil verməlisən?\n- **Əsas nəticə:** Brand kit və istifadə bələdçisi.\n- **Sübut:** oxunan fayl və ya link; uyğun olduqda PDF, cədvəl, PNG, SVG, MP4, SRT, kod və ya layihə faylı.\n- **Qısa hesabat:** 3–5 cümlədə nə etdin, niyə bu üsulu seçdin, nəyi yoxladın?\n- **Mənbələr:** istinadlar, istifadə etdiyin vizual/audio materialın icazəsi.\n\n## Qiymətləndirmə meyarları (100 bal)\n- **40 bal:** Üç əsas fəaliyyətin hər biri real nəticədə görünür.\n- **25 bal:** Nümunə və məntiq yoxlanılıb, nəticə təkrarlana bilir.\n- **15 bal:** Fayl oxunaqlı, düzgün adlandırılıb və bölmələr aydındır.\n- **10 bal:** Məxfilik, müəlliflik və pulsuz istifadə qaydaları gözlənilib.\n- **10 bal:** Öz sözlərinlə yekun və mümkün təkmilləşdirmə izah olunub.\n\n## Göndərməzdən əvvəl yoxla\n- Kontrastı, ölçüləri, mənbə hüququnu və eksportu yoxla.\n- Link başqa şəxsə oxu icazəsi verir, amma sənədin içində şəxsi məlumat və şifrə yoxdur.\n- Lazım olan hissələr sadəcə nəzəri cümlələr deyil, təqdim etdiyin real artefaktla sübut olunur.\n- Ödəniş qəbzi və ya Pro alət tələb olunmur.\n\n[[EN]]\n## Assignment goal: Brand Kit Handoff\nThis practical assignment is designed for beginners. Designs should be legible, original and easy to hand off.\n**Example scenario:** Package logos, colors, type, templates and usage rules in a brand kit.\n\n## Free tools and platforms\n- **Figma Starter** — https://www.figma.com. Use free Starter drafts, frames and text; respect free-plan limits.\n- **Google Docs** — https://docs.google.com/document/. Create a blank document, organize headings/tables and export PDF.\n> No paid subscriptions, ad budgets or paid API keys are required. If a free quota is exhausted, choose a local alternative. Never share passwords, personal data or assets you cannot legally reuse.\n\n## Step-by-step guide\n1. Set up your work folder: Talora / Graphic Design / Task-10. Start a new design file and prepare three rough sketches, canvas sizes and licensed references.\n2. Explain the objective and intended user in one sentence; define what success would look like.\n3. Combine logo and templates. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n4. Write usage rules. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n5. Share editable and exported assets. Show the outcome in a real document, sheet, diagram, design or test rather than describing it only.\n6. Work through the scenario: Package logos, colors, type, templates and usage rules in a brand kit. Document what worked and any limitations.\n7. Complete the main artifact: Brand kit and usage guide. Verify that a reader can open the PDF/file or shared link; keep the editable source too.\n8. Review all three essential actions, then write a three-to-five sentence conclusion listing tools, sources and improvements.\n\n## A worked example\nPackage logos, colors, type, templates and usage rules in a brand kit.\nDo not copy the example unchanged; adapt it to your own fictional scenario and distinguish evidence from assumptions.\n\n## What you must submit\n- **Primary artifact:** Brand kit and usage guide.\n- **Evidence:** a readable file/link or appropriate PDF, spreadsheet, PNG, SVG, MP4, SRT, source code or project file.\n- **Short report:** three to five sentences about your approach, what you verified and why.\n- **Sources:** citations and usage rights for images, audio or reused text.\n\n## Scoring rubric (100 points)\n- **40 points:** all three core actions are shown in the submitted work.\n- **25 points:** tested, accurate, reproducible result or example.\n- **15 points:** readable structure, proper filenames and export format.\n- **10 points:** privacy, licensing and free-tool rules followed.\n- **10 points:** your explanation and suggested improvements.\n\n## Final checklist\n- Check contrast, dimensions, asset rights and exports.\n- Test file permissions; never expose credentials or private data.\n- Provide practical evidence, not theory alone.\n- Do not pay for premium features to complete the task.","new_description":"[[AZ]]\nBrand Kit Handoff: Loqo və şablonları birləşdir. İstifadə qaydası yaz. Edit edilən və eksport faylları paylaş. Pulsuz alətlər: Figma Starter, Google Docs. Nəticə: Brand kit və istifadə bələdçisi.\n\n[[EN]]\nBrand Kit Handoff: Combine logo and templates. Write usage rules. Share editable and exported assets. Free tools: Figma Starter, Google Docs. Output: Brand kit and usage guide."}]$guide_payload$::jsonb);
DO $preflight$
DECLARE matched integer;
BEGIN
 SELECT COUNT(*) INTO matched FROM curriculum_revised c
 CROSS JOIN LATERAL jsonb_array_elements(c.payload) e(item)
 JOIN public.internships i ON i.slug=e.item->>'slug'
 JOIN public.internship_tasks t ON t.internship_id=i.id
   AND t.task_number=(e.item->>'task_number')::integer
   AND t.title=e.item->>'title'
 WHERE t.instructions=e.item->>'old_instructions'
 AND t.description=e.item->>'old_description'
 AND i.slug='talora-graphic-design-2026';
 IF (SELECT jsonb_array_length(payload) FROM curriculum_revised)<>10 OR matched<>10 THEN
  RAISE EXCEPTION 'Content version mismatch for talora-graphic-design-2026; matched %',matched;
 END IF;
END; $preflight$;
UPDATE public.internship_tasks t
SET instructions=e.item->>'new_instructions', description=e.item->>'new_description'
FROM curriculum_revised c
CROSS JOIN LATERAL jsonb_array_elements(c.payload) e(item)
JOIN public.internships i ON i.slug=e.item->>'slug'
WHERE i.slug='talora-graphic-design-2026'
AND t.internship_id=i.id AND t.task_number=(e.item->>'task_number')::integer
AND t.title=e.item->>'title';
DO $verify$
DECLARE matched integer;
BEGIN
 SELECT COUNT(*) INTO matched FROM curriculum_revised c
 CROSS JOIN LATERAL jsonb_array_elements(c.payload) e(item)
 JOIN public.internships i ON i.slug=e.item->>'slug'
 JOIN public.internship_tasks t ON t.internship_id=i.id AND t.task_number=(e.item->>'task_number')::integer
 WHERE t.instructions=e.item->>'new_instructions' AND t.description=e.item->>'new_description'
 AND t.status='published' AND t.is_required AND i.slug='talora-graphic-design-2026';
 IF matched<>10 THEN RAISE EXCEPTION 'Verification failed after update for talora-graphic-design-2026: %',matched; END IF;
END; $verify$;
COMMIT;